var connections = global.get('parat_bridge.connections') || {};
msg = {
    topic: 'connections/update',
    payload: connections
};
return msg;

global.set('utils', {

    build_connection_name: (clients) => {
        return [...clients]
            .sort((a, b) => a.client_system.localeCompare(b.client_system))
            .map(c => `${c.client_system}-${c.identifier}`)
            .join("_");
    },

    build_label: (client) => {
        const colors = {
            wasos:        "#1f871f",
            rayvn:        "#000000",
            parat_bridge: "#b80d18"
        };
        return {
            id:       client.identifier,
            name:     `[${client.client_system}]: ${client.name}`,
            colorHex: colors[client.client_system] || "#888888"
        };
    },

    build_callsign: (client) => `[${client.client_system}: ${client.name}]`,

    FILE_REASONS: {
        OVERSIZED:        "oversized",
        NON_TRANSFERABLE: "non_transferable",
        DOWNLOAD_FAILED:  "download_failed",
        UPLOAD_FAILED:    "upload_failed",
        COMPRESS_FAILED: "compress_failed"
    },

    is_compressible: (mime_type) => {
        if (!mime_type) return false;
        return ['video/', 'audio/', 'image/'].some(prefix => mime_type.startsWith(prefix));
    },

    get_mime_type: (filename) => {
        const ext = (filename || "").split('.').pop().toLowerCase();
        const types = {
            jpg: "image/jpeg", jpeg: "image/jpeg", png: "image/png",
            gif: "image/gif", webp: "image/webp", bmp: "image/bmp",
            svg: "image/svg+xml", heic: "image/heic",
            pdf: "application/pdf",
            mp4: "video/mp4", mov: "video/quicktime", avi: "video/x-msvideo",
            mp3: "audio/mpeg", wav: "audio/wav",
            doc: "application/msword", txt: "text/plain", csv: "text/csv",
            docx: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
            xlsx: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
            zip: "application/zip"
        };
        return types[ext] || null;
    },  

    build_file_key: (message_id, connection_name, filename) => {
        const safe = filename.replace(/[\\\/\:*?"<>|]/g, "_");
        return message_id + "---" + connection_name + "---" + safe;
    },

    parse_file_key: (key) => {
        const raw   = key.startsWith("files.") ? key.slice("files.".length) : key;
        const parts = raw.split("---");
        return {
            message_id:      parts[0]              || null,
            connection_name: parts[1]              || null,
            filename:        parts.slice(2).join("---") || null
        };
    },

    is_bridge_message: (text) => {
        return /\[(?:wasos|rayvn|cim|parat_bridge)(?::|])/.test(text);
    },

    get_system_attributes: (system) => {
        const attributes = {
            rayvn: {
                max_upload_bytes: 1048576, // 1 MB
                can_upload: true,
                can_download: true
            },
            wasos: {
                max_upload_bytes: 1048576, // 10 MB (not a client restriction)
                can_upload: true,
                can_download: true
            },
            cim: {
                max_upload_bytes: null,
                can_upload: false,
                can_download: false
            }
        };
        return attributes[system] || null;
    }

});

return msg;

// Initialize context — sets runtime config only
// Connections and queue are already in cache (loaded by context store on open)
const pb = global.get("parat_bridge") || {};

pb.base_urls = {
    rayvn: "https://api.rayvn.global",
    wasos: "https://dev.wasos.no"
};

if (!pb.queue) pb.queue = { in_flight_connections: [], entry_queue: [] };
pb.queue.in_flight_connections = [];  // always reset on startup

global.set("parat_bridge", pb);

const conns = Object.keys(global.get("parat_bridge.connections") || {}).length;
const queue = (global.get("parat_bridge.queue.entry_queue") || []).length;
node.log("Active: " + conns + " connection(s), " + queue + " queued entries");

return msg;

const connections = global.get("parat_bridge.connections");

if (!connections) {
    msg.payload = [];
    return msg;
}


msg.payload = Object.values(connections).map(conn => {
    const clients = Object.values(conn.clients);
    return {
        "Klient 1": `${clients[0].client_system} — ${clients[0].name}`,
        "Klient 2": `${clients[1].client_system} — ${clients[1].name}`,
        status:     conn.active ? "🟢 aktiv" : "🔴 inaktiv",
        created:    new Date(conn.time_created).toLocaleString()
    };
});


return msg;

let errorLog = global.get('error_log') || [];

// Vis de siste 10 feilene, nyeste først
const recent = errorLog.slice(-10).reverse();

msg.payload = recent.map(e => ({
    time: e.timestamp.replace('T', ' ').substring(0, 19),
    type: e.type.toUpperCase(),
    source: e.source,
    status: e.statusCode || 'none',
    message: e.message.substring(0, 60)
}));

return msg;

/**
 * Build a user-facing notification about file transfer failures.
 * Groups failed files by reason and builds one combined message.
 */
const utils = global.get("utils");
const event = msg.payload;

const groups = {};
for (const f of (event.failed_files || [])) {
    if (!groups[f.reason]) groups[f.reason] = [];
    groups[f.reason].push(f.name);
}

const lines = [];

if (groups[utils.FILE_REASONS.OVERSIZED]) {
    lines.push("⚠️ " + groups[utils.FILE_REASONS.OVERSIZED].length
        + " vedlegg for store for mottakersystemet (maks 1 MB): "
        + groups[utils.FILE_REASONS.OVERSIZED].join(", ") + ".");
}

if (groups[utils.FILE_REASONS.NON_TRANSFERABLE]) {
    lines.push("⚠️ " + groups[utils.FILE_REASONS.NON_TRANSFERABLE].length
        + " vedlegg kan ikke overføres automatisk. "
        + "Tips: Høyreklikk på vedlegg → «Kopier adresse» → lim inn adressen som tekst.");
}

if (groups[utils.FILE_REASONS.DOWNLOAD_FAILED]) {
    lines.push("⚠️ " + groups[utils.FILE_REASONS.DOWNLOAD_FAILED].length
        + " vedlegg kunne ikke lastes ned fra kildesystemet: "
        + groups[utils.FILE_REASONS.DOWNLOAD_FAILED].join(", ") + ".");
}

if (groups[utils.FILE_REASONS.UPLOAD_FAILED]) {
    lines.push("⚠️ " + groups[utils.FILE_REASONS.UPLOAD_FAILED].length
        + " vedlegg ble avvist av mottakersystemet: "
        + groups[utils.FILE_REASONS.UPLOAD_FAILED].join(", ") + ".");
}

if (lines.length === 0) return null;

msg._notification_text = lines.join(" ");
msg._event = event;

return msg;

/**
 * Wrap the notification text in a bridge entry format
 * that can be sent through the queue to the sender's system.
 *
 * The entry is addressed FROM parat_bridge TO the sender.
 * This means it goes to the same system the sender used,
 * so they see the notification in their own interface.
 *
 * client_system is set to 'parat_bridge' so the Filter subflow
 * recognises and drops it when polled back, preventing loops.
 *
 * Returns a clean object — no inherited properties.
 */
const event    = msg._event;
const metadata = event.metadata;
const now      = Date.now();

return {
    topic: "new_message",
    entry: {
        id:        "pb-att-" + now + "-" + Math.random().toString(36).substr(2, 6),
        text:      msg._notification_text,
        timestamp: now,
        author:    "System-melding",
        labels:    [],
        metadata: {
            source: {
                client_system: "parat_bridge",
                name:          "parat_bridge",
                identifier:    "parat_bridge"
            },
            target:          metadata.source,
            connection_name: metadata.connection_name,
            files: null
        }
    }
};
